/**
 * TTOken Code: read a repository's open and recently closed issues, with the
 * pull requests that close them, through one GitHub GraphQL request.
 * Generated by ttoken/apply-brand.mjs from ttoken/forge/issues.ts; edit it there.
 */
import { z } from 'zod'
import type { ForgeFailure, ForgeIssue, ForgeIssueList, ForgeIssuePullRequest, ForgeRepository } from '@deepseek-ai/dsh-experimental-forge'
import type { GraphqlReader } from './commits.ts'

/** Open issues read per board. */
const OPEN_LIMIT = 50
/** Recently closed issues read per board. */
const CLOSED_LIMIT = 10
/** Longest issue body kept, in characters. */
const BODY_LIMIT = 4_000

const ISSUES_QUERY = `query($owner: String!, $name: String!, $open: Int!, $closed: Int!) {
  viewer { login }
  repository(owner: $owner, name: $name) {
    open: issues(states: OPEN, first: $open, orderBy: {field: UPDATED_AT, direction: DESC}) { totalCount nodes { ...BoardIssue } }
    closed: issues(states: CLOSED, first: $closed, orderBy: {field: UPDATED_AT, direction: DESC}) { nodes { ...BoardIssue } }
  }
}
fragment BoardIssue on Issue {
  number title url state body updatedAt
  author { login }
  assignees(first: 5) { nodes { login } }
  labels(first: 10) { nodes { name color } }
  comments { totalCount }
  closedByPullRequestsReferences(first: 5, includeClosedPrs: true) {
    nodes { number url state isDraft commits(last: 1) { nodes { commit { statusCheckRollup { state } } } } }
  }
}`

const issueSchema = z.object({
  number: z.number(),
  title: z.string(),
  url: z.string(),
  state: z.enum(['OPEN', 'CLOSED']),
  body: z.string(),
  updatedAt: z.string(),
  author: z.object({ login: z.string() }).nullable(),
  assignees: z.object({ nodes: z.array(z.object({ login: z.string() })) }),
  labels: z.object({ nodes: z.array(z.object({ name: z.string(), color: z.string() })) }),
  comments: z.object({ totalCount: z.number() }),
  closedByPullRequestsReferences: z.object({
    nodes: z.array(z.object({
      number: z.number(),
      url: z.string(),
      state: z.enum(['OPEN', 'CLOSED', 'MERGED']),
      isDraft: z.boolean(),
      commits: z.object({
        nodes: z.array(z.object({ commit: z.object({ statusCheckRollup: z.object({ state: z.string() }).nullable() }) })),
      }),
    })),
  }),
})

const boardSchema = z.object({
  data: z.object({
    viewer: z.object({ login: z.string() }).nullable().optional(),
    repository: z.object({
      open: z.object({ totalCount: z.number(), nodes: z.array(z.unknown()) }),
      closed: z.object({ nodes: z.array(z.unknown()) }),
    }).nullable(),
  }),
})

/**
 * Read the issues board of one repository.
 * @param read - runs one GraphQL request through `gh`.
 * @param repository - repository on a host this provider serves.
 * @param signal - cancellation of the read.
 * @returns the open and recently closed issues, or why GitHub did not provide them.
 */
export async function readIssues(
  read: GraphqlReader, repository: ForgeRepository, signal: AbortSignal,
): Promise<ForgeIssueList | ForgeFailure> {
  const output = await read(['api', 'graphql', '--hostname', repository.host, '-f', `query=${ISSUES_QUERY}`,
    '-f', `owner=${repository.owner}`, '-f', `name=${repository.name}`, '-F', `open=${OPEN_LIMIT}`, '-F', `closed=${CLOSED_LIMIT}`], signal)
  if (!output.ok) return output.failure
  const parsed = boardSchema.safeParse(output.body)
  if (!parsed.success) return { code: 'unavailable', message: 'unexpected GitHub response to the issue list' }
  const board = parsed.data.data.repository
  if (board === null) return { code: 'not-found', message: `GitHub has no repository ${repository.owner}/${repository.name}` }
  return {
    open: issuesOf(board.open.nodes),
    closed: issuesOf(board.closed.nodes),
    openTotal: board.open.totalCount,
    viewer: parsed.data.data.viewer?.login ?? null,
  }
}

/** Read a check rollup state; a missing rollup is null, and `EXPECTED`, `PENDING` and any later state read as pending. */
function checksOf(state: string | undefined): ForgeIssuePullRequest['checks'] {
  if (state === undefined) return null
  if (state === 'SUCCESS') return 'success'
  if (state === 'FAILURE' || state === 'ERROR') return 'failure'
  return 'pending'
}

/** Map the issue nodes that parse; a node GitHub shapes differently is left out. */
function issuesOf(nodes: readonly unknown[]): ForgeIssue[] {
  return nodes.flatMap((node): ForgeIssue[] => {
    const row = issueSchema.safeParse(node)
    if (!row.success) return []
    const issue = row.data
    return [{
      number: issue.number,
      title: issue.title,
      url: issue.url,
      state: issue.state === 'OPEN' ? 'open' : 'closed',
      body: issue.body.length > BODY_LIMIT ? `${issue.body.slice(0, BODY_LIMIT)}…` : issue.body,
      author: issue.author?.login ?? null,
      assignees: issue.assignees.nodes.map(assignee => assignee.login),
      labels: issue.labels.nodes,
      comments: issue.comments.totalCount,
      updatedAt: issue.updatedAt,
      pullRequests: issue.closedByPullRequestsReferences.nodes.map(pull => ({
        number: pull.number,
        url: pull.url,
        state: pull.state === 'OPEN' ? 'open' : pull.state === 'MERGED' ? 'merged' : 'closed',
        draft: pull.isDraft,
        checks: checksOf(pull.commits.nodes[0]?.commit.statusCheckRollup?.state),
      })),
    }]
  })
}
